import XCTest
@testable import ScionicMerkleTree

/// DataBlock that mirrors Go's tree.Leaf — serializes a string as raw UTF-8 bytes.
/// This is exactly how Go's `tree/tree.go` Leaf.Serialize() works: `return []byte(b.data), nil`
struct GoCompatLeaf: DataBlock {
    let data: String
    func serialize() throws -> Data {
        return Data(data.utf8)
    }
}

/// Cross-compatibility tests: verifies Swift Merkle tree produces IDENTICAL root hashes to Go.
///
/// These expected values were generated by running `TestCrossCompatVectors` in the Go project.
/// If any of these fail, the Swift implementation is NOT compatible with the Go implementation.
final class CrossCompatTests: XCTestCase {

    // MARK: - Test 1: Two leaves ["a", "b"]

    func testTwoLeaves_RootMatchesGo() throws {
        let blocks: [String: DataBlock] = [
            "a": GoCompatLeaf(data: "a"),
            "b": GoCompatLeaf(data: "b"),
        ]

        let tree = try MerkleTree.build(config: nil, blocks: blocks)

        let expectedRoot = "e5a01fee14e0ed5c48714f22180f25ad8365b53f9779f79dc4a3d7e93963f94a"
        XCTAssertEqual(tree.root.hex, expectedRoot, "Root hash mismatch with Go implementation!")
        XCTAssertEqual(tree.depth, 1)
        XCTAssertEqual(tree.proofs.count, 2)
    }

    func testTwoLeaves_ProofsMatchGo() throws {
        let blocks: [String: DataBlock] = [
            "a": GoCompatLeaf(data: "a"),
            "b": GoCompatLeaf(data: "b"),
        ]

        let tree = try MerkleTree.build(config: nil, blocks: blocks)

        // Proof 0: path=1, sibling=SHA256("b")
        XCTAssertEqual(tree.proofs[0].path, 1)
        XCTAssertEqual(tree.proofs[0].siblings[0].hex,
            "3e23e8160039594a33894f6564e1b1348bbd7a0088d42c4acb73eeaed59c009d")

        // Proof 1: path=0, sibling=SHA256("a")
        XCTAssertEqual(tree.proofs[1].path, 0)
        XCTAssertEqual(tree.proofs[1].siblings[0].hex,
            "ca978112ca1bbdcafac231b39a23dc4da786eff8147c4e72b9807785afee48bb")
    }

    // MARK: - Test 2: Three leaves ["x", "y", "z"] (odd count)

    func testThreeLeaves_RootMatchesGo() throws {
        let blocks: [String: DataBlock] = [
            "x": GoCompatLeaf(data: "x"),
            "y": GoCompatLeaf(data: "y"),
            "z": GoCompatLeaf(data: "z"),
        ]

        let tree = try MerkleTree.build(config: nil, blocks: blocks)

        let expectedRoot = "94ee69041d6a31c76688b1da2c00896986f218040c9b41f7118de0b4ee80db98"
        XCTAssertEqual(tree.root.hex, expectedRoot, "Root hash mismatch with Go (3 leaves, odd count)!")
        XCTAssertEqual(tree.depth, 2)
    }

    // MARK: - Test 3: CID-like strings

    func testCIDLikeStrings_RootMatchesGo() throws {
        let blocks: [String: DataBlock] = [
            "bafy2bzacecwv": GoCompatLeaf(data: "bafy2bzacecwv"),
            "bafy2bzacedxyz": GoCompatLeaf(data: "bafy2bzacedxyz"),
            "bafy2bzaceaaaa": GoCompatLeaf(data: "bafy2bzaceaaaa"),
        ]

        let tree = try MerkleTree.build(config: nil, blocks: blocks)

        let expectedRoot = "95343f2d4bfe65b2b65f1f3f7a80b5687ff4fbceb27c18a48706e10d2b5cf76a"
        XCTAssertEqual(tree.root.hex, expectedRoot, "Root hash mismatch with Go (CID-like strings)!")
    }

    // MARK: - Test 4: Five leaves with different keys/values

    func testFiveLeaves_RootMatchesGo() throws {
        let blocks: [String: DataBlock] = [
            "key1": GoCompatLeaf(data: "value1"),
            "key2": GoCompatLeaf(data: "value2"),
            "key3": GoCompatLeaf(data: "value3"),
            "key4": GoCompatLeaf(data: "value4"),
            "key5": GoCompatLeaf(data: "value5"),
        ]

        let tree = try MerkleTree.build(config: nil, blocks: blocks)

        let expectedRoot = "35710a651ac18658280658bd93b0d0cdd27ca6adcebba2083c694018204c4384"
        XCTAssertEqual(tree.root.hex, expectedRoot, "Root hash mismatch with Go (5 leaves)!")
        XCTAssertEqual(tree.depth, 3)
    }
}

// MARK: - Helper

extension Data {
    /// Hex string representation for test assertions.
    var hex: String {
        map { String(format: "%02x", $0) }.joined()
    }
}